const { withAppBuildGradle } = require('expo/config-plugins');

// Expo CLI's export:embed (this project's RN Gradle bundleCommand) resolves
// this monorepo's workspace root (two levels above apps/mobile) as Metro's
// project root, but the RN Gradle plugin relativizes entryFile/bundleFile
// against `react.root` (default: apps/mobile) before invoking it — the two
// disagree on what a relative path means, so a local `assembleRelease`
// always failed with "Unable to resolve module ../../src/index.tsx".
// Pointing react.root at the actual repo root makes both sides agree.
// `android/` is regenerated by `expo prebuild`, so this has to be a config
// plugin rather than a one-off edit to survive it.
module.exports = function withKssengerReleaseBundleRoot(config) {
  return withAppBuildGradle(config, (buildGradleConfig) => {
    const marker = 'root = file("../../../../")';
    if (buildGradleConfig.modResults.contents.includes(marker)) return buildGradleConfig;
    buildGradleConfig.modResults.contents = buildGradleConfig.modResults.contents.replace(
      /react\s*\{/,
      `react {\n    ${marker}`,
    );
    return buildGradleConfig;
  });
};
